function isValidSlug(s) {
  // BUG: nested quantifiers /^([a-z]+)+$/ backtrack exponentially on a long
  // non-matching input (ReDoS).
  return /^([a-z]+)+$/.test(s);
}

module.exports = { isValidSlug };

test_setup_files.behavior_test.js:
const assert = require('node:assert');
const { isValidSlug } = require('./validate.js');

// correctness: exactly one-or-more lowercase letters, whole string
assert.strictEqual(isValidSlug('hello'), true);
assert.strictEqual(isValidSlug('a'), true);
assert.strictEqual(isValidSlug(''), false);
assert.strictEqual(isValidSlug('ab1'), false);
assert.strictEqual(isValidSlug('AB'), false);
assert.strictEqual(isValidSlug('a-b'), false);

// ReDoS: a crafted non-matching input must be rejected quickly, not hang
const evil = 'a'.repeat(28) + '!';
const t0 = Date.now();
const result = isValidSlug(evil);
const elapsedMs = Date.now() - t0;
assert.strictEqual(result, false);
assert.ok(
  elapsedMs < 1500,
  `isValidSlug took ${elapsedMs}ms on a crafted input - catastrophic backtracking (ReDoS)`
);

console.log('ok');

